CREATE OR REPLACE FUNCTION public.tenh_guard_branch_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if tg_op='UPDATE' and new.business_id<>old.business_id then raise exception 'Records cannot move between businesses.'; end if;
 if new.location_id is null then
  select id into new.location_id from business_locations where business_id=new.business_id and is_default and is_active;
  if new.location_id is null then raise exception 'Set an active default branch first.'; end if;
 end if;
 perform tenh_assert_plan_branch(new.business_id,new.location_id);
 if tg_table_name='product_location_stock' then
  if not exists(select 1 from products where id=new.product_id and business_id=new.business_id) then raise exception 'Product does not belong to this business.'; end if;
 end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION public.tenh_assign_order_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.order_code is null then new.order_code := public.tenh_new_order_code(); end if;
  if tg_op = 'UPDATE' and old.order_code is not null and new.order_code is distinct from old.order_code then
    raise exception 'An order code cannot be changed.';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.tenh_pos_restore_points()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_used public.tenh_pos_points_used%rowtype;
begin
  if new.status::text in ('cancelled','refunded') and old.status is distinct from new.status then
    update public.tenh_pos_points_used set restored_at=clock_timestamp() where order_id=new.id and restored_at is null returning * into v_used;
    if v_used.order_id is not null then
      update public.customers set loyalty_points=loyalty_points+v_used.points,updated_at=clock_timestamp() where id=v_used.customer_id and business_id=v_used.business_id;
      insert into public.customer_loyalty_transactions(business_id,customer_id,transaction_type,points,note)
        values(v_used.business_id,v_used.customer_id,'adjustment',v_used.points,'Restored redeemed points on reversed POS order '||new.order_number);
    end if;
  end if;
  return new;
end $function$

